    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">CO = 9</span>  و  <span dir=\"ltr\" class=\"expr pt\">HO = 15</span>  و  <span dir=\"ltr\" class=\"expr pt\">IK = 30</span>  و  <span dir=\"ltr\" class=\"expr pt\">(HO) // (IK)</span>"},{"quoi":"في المثلّث CKI لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(OH) // (KI)</span>  و  <span dir=\"ltr\" class=\"expr pt\">O ∈ (CK)</span>  و  <span dir=\"ltr\" class=\"expr pt\">H ∈ (CI)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">CO</span><span class=\"den\">CK</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CH</span><span class=\"den\">CI</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">OH</span><span class=\"den\">KI</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">15</span><span class=\"den\">30</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">9</span><span class=\"den\">CK</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CK = 18</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">CK = 18</span>  و  <span dir=\"ltr\" class=\"expr pt\">CO = 9</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">KO = 9</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">KO = 18 − 9</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">KO = 9</span>"}],
