    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">CR = 1,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">CK = 6,3</span>  و  <span dir=\"ltr\" class=\"expr pt\">CS = 8,4</span>  و  <span dir=\"ltr\" class=\"expr pt\">(OR) // (KS)</span>"},{"quoi":"في المثلّث CKS لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RO) // (KS)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (CK)</span>  و  <span dir=\"ltr\" class=\"expr pt\">O ∈ (CS)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">CR</span><span class=\"den\">CK</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CO</span><span class=\"den\">CS</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RO</span><span class=\"den\">KS</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">1,8</span><span class=\"den\">6,3</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CO</span><span class=\"den\">8,4</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CO = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CO = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>"}],
