    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AR = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">QR = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 4,5</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 10,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">(QR) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(PR) // (BC)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">x = CD.</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AR = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 3</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AC = 9</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">AC = 6 + 3</span>"},{"quoi":"في المثلّث ACD لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RQ) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">Q ∈ (AD)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AQ</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RQ</span><span class=\"den\">CD</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6</span><span class=\"den\">9</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">CD</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CD = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">9</span><span class=\"den\">2</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CD = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">9</span><span class=\"den\">2</span></span>"},{"quoi":"2)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">y = QP.</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">CD =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">9</span><span class=\"den\">2</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 4,5</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BC = 9</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BC =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + 4,5"},{"quoi":"في المثلّث ACB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RP) // (CB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">P ∈ (AB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RP</span><span class=\"den\">CB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6</span><span class=\"den\">9</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">PR</span><span class=\"den\">9</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">PR = 6</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">PR = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">QR = 3</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">PQ = 3</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">PQ = 6 − 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">PQ = 3</span>"},{"quoi":"3)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">z = PB.</span>"},{"quoi":"في المثلّث ACB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RP) // (CB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">P ∈ (AB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RP</span><span class=\"den\">CB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6</span><span class=\"den\">9</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">10,8</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AP = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">36</span><span class=\"den\">5</span></span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 10,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">AP =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">36</span><span class=\"den\">5</span></span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BP =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">18</span><span class=\"den\">5</span></span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BP = 10,8 −</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">36</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BP = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">18</span><span class=\"den\">5</span></span>"}],
