    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AR = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">QR = 6,25</span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 7,5</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 16</span>  و  <span dir=\"ltr\" class=\"expr pt\">(QR) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(PR) // (BC)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">x = CD.</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AR = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 6</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AC = 12</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">AC = 6 + 6</span>"},{"quoi":"في المثلّث ACD لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RQ) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">Q ∈ (AD)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AQ</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RQ</span><span class=\"den\">CD</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6</span><span class=\"den\">12</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">6,25</span><span class=\"den\">CD</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CD = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">25</span><span class=\"den\">2</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CD = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">25</span><span class=\"den\">2</span></span>"},{"quoi":"2)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">y = QP.</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">CD =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">25</span><span class=\"den\">2</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 7,5</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BC = 20</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BC =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">25</span><span class=\"den\">2</span></span> + 7,5"},{"quoi":"في المثلّث ACB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RP) // (CB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">P ∈ (AB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RP</span><span class=\"den\">CB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6</span><span class=\"den\">12</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">PR</span><span class=\"den\">20</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">PR = 10</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">PR = 10</span>  و  <span dir=\"ltr\" class=\"expr pt\">QR = 6,25</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">PQ =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">15</span><span class=\"den\">4</span></span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">PQ = 10 − 6,25</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">PQ = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">15</span><span class=\"den\">4</span></span>"},{"quoi":"3)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">z = PB.</span>"},{"quoi":"في المثلّث ACB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RP) // (CB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">P ∈ (AB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RP</span><span class=\"den\">CB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6</span><span class=\"den\">12</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">16</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AP = 8</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 16</span>  و  <span dir=\"ltr\" class=\"expr pt\">AP = 8</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BP = 8</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BP = 16 − 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BP = 8</span>"}],
